import 'dart:convert';

import 'package:flutter/services.dart';

import '../core/paths.dart';

/// One completion candidate.
class Suggestion {
  const Suggestion(this.word, this.type, {this.isKey = true});
  final String word;
  final String type;
  final bool isKey;
}

/// sing-box JSON schema (generated by the core itself with `sing-box schema`)
/// and a cursor-aware completion engine on top of it.
class ConfigSchema {
  ConfigSchema._(this._root);
  final Map<String, dynamic> _root;

  static ConfigSchema? _i;

  static Future<ConfigSchema> load() async {
    if (_i != null) return _i!;
    String text;
    final f = Paths.I.schemaFile;
    if (await f.exists()) {
      text = await f.readAsString();
    } else {
      text = await rootBundle.loadString('assets/schema/sing-box.schema.json');
    }
    return _i = ConfigSchema._(jsonDecode(text) as Map<String, dynamic>);
  }

  Map<String, dynamic> get _defs => (_root[r'$defs'] as Map).cast<String, dynamic>();

  Map<String, dynamic> _deref(Map<String, dynamic> s) {
    var cur = s;
    for (var i = 0; i < 8 && cur[r'$ref'] is String; i++) {
      final name = (cur[r'$ref'] as String).split('/').last;
      cur = (_defs[name] as Map).cast<String, dynamic>();
    }
    return cur;
  }

  /// Object variants of a schema node (oneOf / anyOf flattened).
  List<Map<String, dynamic>> _variants(Map<String, dynamic> s) {
    s = _deref(s);
    final alts = (s['oneOf'] ?? s['anyOf']) as List?;
    if (alts == null) return [s];
    return [for (final a in alts) ..._variants((a as Map).cast<String, dynamic>())];
  }

  String? _typeConst(Map<String, dynamic> v) {
    final t = (v['properties'] as Map?)?['type'];
    return t is Map ? t['const'] as String? : null;
  }

  /// Properties of the object at [s], picking the variant whose `type` const
  /// matches [type] when the node is polymorphic.
  Map<String, Map<String, dynamic>> properties(Map<String, dynamic> s, String? type) {
    final vs = _variants(s).where((v) => v['properties'] is Map).toList();
    final chosen = type == null ? vs : vs.where((v) => _typeConst(v) == type).toList();
    final out = <String, Map<String, dynamic>>{};
    for (final v in (chosen.isEmpty ? vs : chosen)) {
      (v['properties'] as Map).forEach((k, p) => out.putIfAbsent(k as String, () => (p as Map).cast<String, dynamic>()));
    }
    // `type` on a polymorphic node: offer every variant's const.
    if (vs.length > 1 && out.containsKey('type')) {
      out['type'] = {'enum': [for (final v in vs) ?_typeConst(v)], 'type': 'string'};
    }
    return out;
  }

  Map<String, dynamic>? _items(Map<String, dynamic> s) {
    for (final v in _variants(s)) {
      if (v['items'] is Map) return (v['items'] as Map).cast<String, dynamic>();
    }
    return null;
  }

  String describe(Map<String, dynamic> s) {
    final ref = s[r'$ref'] as String?;
    if (ref != null) {
      final name = ref.split('/').last;
      if (name == 'Duration') return 'duration';
      final d = _deref(s);
      if (d['type'] is String && d['type'] != 'object') return d['type'];
      return name;
    }
    if (s['x-tag-reference'] != null) return '→ ${s['x-tag-reference']}';
    final t = s['type'];
    if (t == 'array') {
      final it = s['items'];
      return it is Map ? '${describe(it.cast<String, dynamic>())}[]' : 'array';
    }
    if (t is String) return t;
    if (s['anyOf'] != null || s['oneOf'] != null) {
      final ts = <String>{};
      for (final a in ((s['anyOf'] ?? s['oneOf']) as List)) {
        ts.add(describe((a as Map).cast<String, dynamic>()));
      }
      return ts.join(' | ');
    }
    return 'any';
  }

  /// Completions for [text] with the caret at [offset]. Returns the partial
  /// word being typed and the candidates, or null when nothing applies.
  (String, List<Suggestion>)? complete(String text, int offset) {
    final ctx = _Scanner(text, offset).run();
    if (ctx == null) return null;

    // Walk the schema along the path to the innermost container.
    var node = _root;
    for (final seg in ctx.path) {
      if (seg.key == null) {
        final it = _items(node);
        if (it == null) return null;
        node = it;
      } else {
        final p = properties(node, seg.type)[seg.key];
        if (p == null) return null;
        node = p;
      }
    }

    if (ctx.expectKey) {
      final props = properties(node, ctx.innerType);
      final out = <Suggestion>[];
      props.forEach((k, v) {
        if (ctx.siblingKeys.contains(k) || !k.startsWith(ctx.word) || k == ctx.word) return;
        out.add(Suggestion(k, describe(v)));
      });
      return out.isEmpty ? null : (ctx.word, out);
    }

    // Value position.
    Map<String, dynamic>? vs;
    if (ctx.valueKey != null) {
      vs = properties(node, ctx.innerType)[ctx.valueKey];
    } else {
      vs = _items(node);
    }
    if (vs == null) return null;
    final values = <Suggestion>[];
    void addEnum(Map<String, dynamic> s) {
      for (final v in _variants(s)) {
        for (final e in (v['enum'] as List? ?? [])) {
          values.add(Suggestion('$e', 'enum', isKey: false));
        }
        if (v['const'] != null) values.add(Suggestion('${v['const']}', 'const', isKey: false));
        if (v['type'] == 'array' && v['items'] is Map) addEnum((v['items'] as Map).cast<String, dynamic>());
      }
    }

    addEnum(vs);
    final ref = vs['x-tag-reference'] ?? (vs['items'] is Map ? vs['items']['x-tag-reference'] : null);
    if (ref != null) {
      for (final t in _tags(text, ref as String)) {
        values.add(Suggestion(t, '→ $ref', isKey: false));
      }
    }
    final seen = <String>{};
    final out = [
      for (final s in values)
        if (s.word.startsWith(ctx.word) && s.word != ctx.word && seen.add(s.word)) s
    ];
    return out.isEmpty ? null : (ctx.word, out);
  }

  static const _sections = {
    'outbound': ['outbounds', 'endpoints'],
    'inbound': ['inbounds'],
    'rule_set': ['rule_set'],
    'dns_server': ['servers'],
    'endpoint': ['endpoints'],
  };

  /// Tags declared in the document for a reference kind; falls back to every
  /// tag when the text does not parse yet.
  List<String> _tags(String text, String kind) {
    final out = <String>[];
    try {
      final j = jsonDecode(text) as Map<String, dynamic>;
      void collect(dynamic list) {
        if (list is! List) return;
        for (final e in list) {
          if (e is Map && e['tag'] is String) out.add(e['tag']);
        }
      }

      for (final sec in _sections[kind] ?? const <String>[]) {
        collect(j[sec]);
        collect((j['route'] as Map?)?[sec]);
        collect((j['dns'] as Map?)?[sec]);
      }
      if (out.isNotEmpty) return out;
    } catch (_) {}
    for (final m in RegExp(r'"tag"\s*:\s*"([^"]+)"').allMatches(text)) {
      out.add(m.group(1)!);
    }
    return out;
  }
}

class _Seg {
  _Seg(this.key, this.type);

  /// Object key, or null for an array item.
  final String? key;

  /// `type` value of the object that holds [key].
  final String? type;
}

class _Ctx {
  _Ctx(this.path, this.innerType, this.expectKey, this.valueKey, this.word, this.siblingKeys);
  final List<_Seg> path;
  final String? innerType;
  final bool expectKey;
  final String? valueKey;
  final String word;
  final Set<String> siblingKeys;
}

class _Frame {
  _Frame(this.isObject, this.start);
  final bool isObject;
  final int start;
  String? key;
}

/// Tolerant scan of (possibly unfinished) JSON up to the caret.
class _Scanner {
  _Scanner(this.text, this.offset);
  final String text;
  final int offset;

  _Ctx? run() {
    final stack = <_Frame>[];
    String? lastString;
    var lastSig = '';
    var i = 0;
    var inString = false;
    var stringStart = 0;
    while (i < offset && i < text.length) {
      final c = text[i];
      if (inString) {
        if (c == r'\') {
          i += 2;
          continue;
        }
        if (c == '"') {
          inString = false;
          lastString = text.substring(stringStart + 1, i);
          lastSig = '"';
        }
        i++;
        continue;
      }
      switch (c) {
        case '"':
          inString = true;
          stringStart = i;
        case '{':
          stack.add(_Frame(true, i));
          lastSig = c;
        case '[':
          stack.add(_Frame(false, i));
          lastSig = c;
        case '}' || ']':
          if (stack.isNotEmpty) stack.removeLast();
          lastSig = c;
        case ':':
          if (stack.isNotEmpty && stack.last.isObject) stack.last.key = lastString;
          lastSig = c;
        case ',':
          if (stack.isNotEmpty && stack.last.isObject) stack.last.key = null;
          lastSig = c;
        default:
          if (c.trim().isNotEmpty) lastSig = c;
      }
      i++;
    }
    if (stack.isEmpty) return null;

    // The partial word at the caret.
    var w = offset;
    while (w > 0 && RegExp(r'[A-Za-z0-9_\-.!@]').hasMatch(text[w - 1])) {
      w--;
    }
    final word = text.substring(w, offset);
    final quoted = inString;
    final before = quoted ? _prevSig(stringStart) : lastSig;

    final top = stack.last;
    bool expectKey;
    String? valueKey;
    if (top.isObject) {
      if (before == '{' || before == ',') {
        expectKey = true;
      } else if (before == ':') {
        expectKey = false;
        valueKey = top.key;
      } else {
        return null;
      }
    } else {
      if (before != '[' && before != ',') return null;
      expectKey = false;
    }
    if (!quoted && expectKey) return null;
    if (word.isEmpty && !quoted) return null;

    final path = <_Seg>[];
    for (var k = 1; k < stack.length; k++) {
      final parent = stack[k - 1];
      path.add(_Seg(parent.isObject ? parent.key : null, parent.isObject ? _typeOf(parent.start) : null));
    }
    final inner = top.isObject ? _typeOf(top.start) : null;
    final siblings = top.isObject ? _keysOf(top.start) : <String>{};
    return _Ctx(path, inner, expectKey, valueKey, word, siblings);
  }

  String _prevSig(int from) {
    for (var j = from - 1; j >= 0; j--) {
      final c = text[j];
      if (c.trim().isNotEmpty) return c;
    }
    return '';
  }

  /// Walks the object opened at [start] (to its end, past the caret) and
  /// yields its direct key/value pairs.
  Iterable<(String, String?)> _pairs(int start) sync* {
    var depth = 0;
    var i = start;
    String? lastStr;
    String? pendingKey;
    while (i < text.length) {
      final c = text[i];
      if (c == '"') {
        final s = i;
        i++;
        while (i < text.length && text[i] != '"') {
          if (text[i] == r'\') i++;
          i++;
        }
        lastStr = text.substring(s + 1, i.clamp(s + 1, text.length));
        if (depth == 1 && pendingKey != null) {
          yield (pendingKey, lastStr);
          pendingKey = null;
        }
      } else if (c == '{' || c == '[') {
        depth++;
        if (depth == 2 && pendingKey != null) {
          yield (pendingKey, null);
          pendingKey = null;
        }
      } else if (c == '}' || c == ']') {
        depth--;
        if (depth == 0) return;
      } else if (c == ':' && depth == 1) {
        pendingKey = lastStr;
      } else if (c == ',' && depth == 1) {
        if (pendingKey != null) yield (pendingKey, null);
        pendingKey = null;
      }
      i++;
    }
  }

  String? _typeOf(int start) {
    for (final (k, v) in _pairs(start)) {
      if (k == 'type') return v;
    }
    return null;
  }

  Set<String> _keysOf(int start) => {for (final (k, _) in _pairs(start)) k};
}
